<script setup lang="ts">
import { computed, defineAsyncComponent, inject, onBeforeUnmount, onMounted, ref, watch, type ComputedRef } from 'vue';
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router';
import { ArrowLeft, ArrowRight, Download, ExternalLink, FileArchive, FilePenLine, FileText, History, Image, Layers3, LoaderCircle, MessageSquareText, RefreshCw, Search, Table2, Tags, X } from 'lucide-vue-next';
import type { BranchItem, FilePreview, LabelColumn, LabelState, RepositoryPermissions } from '@oxen/shared';
import { queryString, request } from '../api';
import { useAppStore } from '../stores/app';
const PdfPreview = defineAsyncComponent(() => import('./PdfPreview.vue'));
const ArchivePreview = defineAsyncComponent(() => import('./ArchivePreview.vue'));
const LabelManager = defineAsyncComponent(() => import('./LabelManager.vue'));
const props = defineProps<{ base: string; branch: string; path: string; compact?: boolean }>();
const emit = defineEmits<{ close: []; open: [path: string] }>();
const route = useRoute(), router=useRouter(), app=useAppStore();
const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const writable=computed(()=>permissions?.value.write===true&&app.status?.capabilities.write!==false);
interface LabelEditorHandle{hasUnsavedChanges:boolean;busy:boolean;discardUnsavedChanges:()=>void}
const fileLabelEditor=ref<LabelEditorHandle|null>(null), rowLabelEditor=ref<LabelEditorHandle|null>(null);
async function allowEditorNavigation(...editors:Array<LabelEditorHandle|null>){
  const current=generation;
  if(editors.some(editor=>editor?.busy)){app.notify('标签正在提交，请等待完成后再切换。');return false;}
  const dirtyEditors=editors.filter((editor):editor is LabelEditorHandle=>!!editor?.hasUnsavedChanges);
  if(!dirtyEditors.length)return true;
  if(!(await app.confirmAction('当前标签或列配置尚未保存，确认放弃并切换吗？',{title:'未保存的标签',confirmLabel:'放弃并切换'}))||current!==generation)return false;
  dirtyEditors.forEach(editor=>editor.discardUnsavedChanges());return true;
}
async function closeRow(){const current=generation;if(await allowEditorNavigation(rowLabelEditor.value)&&current===generation)selectedRow.value=undefined;}
async function toggleFileLabels(){
  const current=generation,open=!showFileLabels.value;
  if(!(await allowEditorNavigation(fileLabelEditor.value,rowLabelEditor.value))||current!==generation)return;
  if(open)selectedRow.value=undefined;
  showFileLabels.value=open;
}
const preview = ref<FilePreview>(), error = ref(''), loading = ref(true), page = ref(1), search = ref(''), queryDraft=ref(''), viewCommit = ref('');
const labels = ref<LabelState>(), labelError = ref(''), showFileLabels = ref(false);
const selectedRow = ref<{record: Record<string, unknown>; rowId?: string; ordinal: number}>();
let generation = 0, labelGeneration = 0;
const pageSize = 50;
const rawUrl = computed(() => '/api' + props.base + '/raw' + queryString({ ref: viewCommit.value || props.branch, path: props.path }));
const columns = computed(() => preview.value?.columns ?? []);
const rowLabelColumns=computed(()=>labels.value?.columns.filter(column=>!column.scopes?.length||column.scopes.includes('row'))??[]);
const rows = computed(() => (preview.value?.rows ?? []).filter(row => JSON.stringify(row).toLowerCase().includes(search.value.toLowerCase())));
const lines = computed(() => preview.value?.text?.split('\n') ?? []);
const pageCount = computed(() => Math.max(1, Math.ceil((preview.value?.totalRows ?? 0) / (preview.value?.pageSize ?? pageSize))));
const scopeBadges = computed(() => (labels.value?.assignments ?? []).filter(item => item.scope === 'dataset' || item.scope === 'file' && item.path === props.path).flatMap(item => Object.entries(item.values).map(([id, value]) => ({ scope: item.scope === 'dataset' ? '数据集' : '文件', name: labels.value?.columns.find(column => column.id === id)?.name ?? id, value: Array.isArray(value) ? value.join('、') : value }))));
function resourceLink(tab:string){return {path:`/repos/${encodeURIComponent(String(route.params.namespace))}/${encodeURIComponent(String(route.params.repo))}/${tab}`,query:{branch:props.branch,path:props.path}};}
const structuredEditable=computed(()=>/\.(jsonl|ndjson)$/i.test(props.path));
const editLink=computed(()=>structuredEditable.value?resourceLink('table'):{...resourceLink('workspaces'),query:{branch:props.branch,path:preview.value?.kind==='table'?props.path.split('/').slice(0,-1).join('/'):props.path,action:preview.value?.kind==='table'?'upload':'edit-file'}});
function goQuery(){return router.push({...resourceLink('query'),query:{branch:props.branch,path:props.path,...(queryDraft.value.trim()?{prompt:queryDraft.value.trim()}:{}),engine:'model'}});}
function pretty(value: unknown) { return value === null ? 'null' : typeof value === 'object' ? JSON.stringify(value, null, 2) : String(value ?? ''); }
function linked(value: unknown) { return typeof value === 'string' && !value.includes('..') && !value.startsWith('/') && !/^[a-z]+:/i.test(value) && /\.(zip|txt|md|json|jsonl|ndjson|pdf)$/i.test(value); }
function indexFor(row: Record<string, unknown>) { return preview.value?.rows?.indexOf(row) ?? -1; }
function rowIdFor(row: Record<string, unknown>) { const index = indexFor(row); const value = preview.value?.rowIds?.[index] ?? row._oxen_row_id ?? row._oxen_id; return value === undefined ? undefined : String(value); }
function rowNumber(row: Record<string, unknown>) { return (page.value - 1) * (preview.value?.pageSize ?? pageSize) + indexFor(row) + 1; }
function labelValue(row: Record<string, unknown>, column: LabelColumn) { const id = rowIdFor(row); if (!id) return undefined; return labels.value?.assignments.find(item => item.scope === 'row' && item.path === props.path && item.rowId === id)?.values[column.id]; }
function annotationLink(row?: Record<string, unknown>) { return { path: `/repos/${encodeURIComponent(String(route.params.namespace))}/${encodeURIComponent(String(route.params.repo))}/annotations`, query: { branch: props.branch, path: props.path, page: String(page.value), ...(row && rowIdFor(row) ? { row: rowIdFor(row) } : {}) } }; }
async function openRow(row: Record<string, unknown>) {
  const current=generation;
  if(!(await allowEditorNavigation(fileLabelEditor.value,rowLabelEditor.value))||current!==generation||indexFor(row)<0)return;
  showFileLabels.value=false;
  selectedRow.value = { record: row, rowId: rowIdFor(row), ordinal: rowNumber(row) };
}
async function moveRow(direction:number){
  const current=generation;
  if(!selectedRow.value||loading.value||!(await allowEditorNavigation(rowLabelEditor.value))||current!==generation)return;
  const next=indexFor(selectedRow.value.record)+direction;
  if(next>=0&&next<(preview.value?.rows?.length??0)){await openRow(preview.value!.rows![next]!);return;}
  const nextPage=page.value+direction;if(nextPage<1||nextPage>pageCount.value)return;
  page.value=nextPage;selectedRow.value=undefined;const expected=generation+1;await load();
  if(expected===generation&&!error.value&&preview.value?.rows?.length)await openRow(preview.value.rows[direction>0?0:preview.value.rows.length-1]!);
}
async function loadLabels(reference: string, current: number) {
  const labelRequest = ++labelGeneration;
  try { const state = await request<LabelState>(props.base + '/labels' + queryString({ ref: reference })); if (current === generation && labelRequest === labelGeneration) { labels.value = state; labelError.value = ''; } }
  catch (cause) { if (current === generation && labelRequest === labelGeneration) labelError.value = (cause as Error).message; }
}
async function load() {
  const current = ++generation; loading.value = true; error.value = '';
  try {
    let reference = viewCommit.value;
    if (!reference) {
      if (/^[a-f0-9]{32,64}$/i.test(props.branch)) reference = props.branch;
      else { const branches = await request<BranchItem[]>(props.base + '/branches'); if (current !== generation) return; reference = branches.find(branch => branch.name === props.branch)?.commitId || props.branch; }
    }
    const value = await request<FilePreview>(props.base + '/file' + queryString({ ref: reference, path: props.path, page: page.value, pageSize }));
    if (current !== generation) return;
    preview.value = value; viewCommit.value = reference;
    if (!props.compact) void loadLabels(reference, current);
  } catch (cause) { if (current === generation) error.value = (cause as Error).message; }
  finally { if (current === generation) loading.value = false; }
}
async function refresh() {if(!(await allowEditorNavigation(fileLabelEditor.value,rowLabelEditor.value)))return;viewCommit.value = ''; selectedRow.value = undefined; void load(); }
function labelsChanged(state: LabelState) { ++labelGeneration; labels.value = state; viewCommit.value = state.commitId; }
async function changePage(next: number) { if (loading.value||!(await allowEditorNavigation(rowLabelEditor.value))) return; page.value = Math.max(1, Math.min(pageCount.value, next)); selectedRow.value = undefined; await load(); }
watch(() => [props.base, props.path, props.branch], () => { page.value = 1; search.value = ''; queryDraft.value = ''; viewCommit.value = ''; labels.value = undefined; selectedRow.value = undefined; void load(); }, { immediate: true });
onBeforeRouteLeave(()=>allowEditorNavigation(fileLabelEditor.value,rowLabelEditor.value));
onBeforeRouteUpdate((to,from)=>{const changed=['namespace','repo','tab'].some(key=>to.params[key]!==from.params[key])||['branch','path','file'].some(key=>to.query[key]!==from.query[key]);return changed?allowEditorNavigation(fileLabelEditor.value,rowLabelEditor.value):true;});
function beforeUnload(event:BeforeUnloadEvent){if(!fileLabelEditor.value?.hasUnsavedChanges&&!fileLabelEditor.value?.busy&&!rowLabelEditor.value?.hasUnsavedChanges&&!rowLabelEditor.value?.busy)return;event.preventDefault();event.returnValue='';}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));
onBeforeUnmount(() => { ++generation;window.removeEventListener('beforeunload',beforeUnload); });
</script>

<template>
  <section class="file-preview" :class="{ compact }">
    <div class="preview-toolbar"><div class="resource-title"><component :is="/\.zip$/i.test(path)?FileArchive:preview?.kind === 'table' ? Table2 : preview?.kind === 'image' ? Image : FileText" :size="17" /><strong>{{ path.split('/').pop() }}</strong><span v-if="preview" class="badge">{{ /\.zip$/i.test(path)?'ZIP 包':preview.kind === 'table' ? '数据集' : preview.kind === 'text' ? '文本' : preview.kind.toUpperCase() }}</span><span v-if="preview" class="resource-size">{{preview.size.toLocaleString()}} B</span></div><div class="resource-actions"><RouterLink v-if="!compact" :to="resourceLink('commits')" class="btn btn-ghost" title="查看提交历史"><History :size="15"/><span>历史</span></RouterLink><RouterLink v-if="!compact&&writable&&preview&&['table','text'].includes(preview.kind)" :to="editLink" class="btn btn-ghost" :title="preview.kind==='table'&&!structuredEditable?'上传修改后的文件版本':'编辑数据文件'"><FilePenLine :size="15"/><span>{{preview.kind==='table'&&!structuredEditable?'替换文件':'编辑'}}</span></RouterLink><button v-if="!compact" class="btn btn-ghost" aria-label="文件标签" :aria-expanded="showFileLabels" @click="toggleFileLabels"><Tags :size="15" /><span>文件标签</span></button><button v-if="!compact" class="icon-button" aria-label="刷新到最新文件版本" :disabled="loading" @click="refresh"><RefreshCw :size="15" :class="{spin:loading}"/></button><a :href="rawUrl" class="btn btn-ghost" target="_blank" rel="noreferrer" title="打开原文件"><Download :size="15" /><span>原文件</span></a><button v-if="compact" class="icon-button" aria-label="关闭关联预览" @click="emit('close')"><X :size="18" /></button></div></div>
    <div v-if="!compact && scopeBadges.length" class="scope-badges"><span v-for="(badge,index) in scopeBadges" :key="index"><small>{{ badge.scope }}</small><strong>{{ badge.name }}</strong>{{ badge.value }}</span></div>
    <div v-if="showFileLabels && !compact" class="file-label-manager"><LabelManager ref="fileLabelEditor" :base="base" :branch="branch" scope="file" :path="path" :commit-id="viewCommit || undefined" @changed="labelsChanged" @loaded="labels = $event" @refresh="refresh" /></div>
    <div v-if="loading" class="empty"><LoaderCircle class="spin" :size="24" /><p>正在读取文件…</p></div>
    <div v-else-if="error" class="error-state">{{ error }}<button class="btn" @click="load">重试</button></div>
    <template v-else-if="preview">
      <template v-if="preview.kind === 'table'">
        <form v-if="!compact" class="dataset-query-bar" @submit.prevent="goQuery"><Search :size="18"/><input v-model="queryDraft" aria-label="查询完整数据集" placeholder="搜索或提问，例如：label 等于 1，按攻击类型统计…"/><button type="submit" class="btn"><MessageSquareText :size="15"/>查询数据<ArrowRight :size="14"/></button></form>
        <div class="table-tools"><div class="table-metadata"><strong>{{ preview.totalRows?.toLocaleString() }} <span>行</span></strong><span>{{ columns.length }} 个字段<span v-if="rowLabelColumns.length"> + {{ rowLabelColumns.length }} 个标签列</span></span><code v-if="viewCommit" class="preview-version" :title="viewCommit">{{viewCommit.slice(0,10)}}</code></div><div class="table-tool-actions"><label class="search-field small-search"><Search :size="14" /><input v-model="search" aria-label="过滤当前页" placeholder="筛选当前页…" /></label><RouterLink v-if="!compact" :to="annotationLink()" class="btn btn-ghost"><Tags :size="15" /> 标注</RouterLink></div></div>
        <p v-if="labelError && !compact" class="table-label-error">标签列未能读取：{{ labelError }}</p>
        <div class="table-scroll"><table class="data-table preview-table"><thead><tr><th class="row-index">#</th><th v-for="column in columns" :key="column.name">{{ column.name }}<small>{{ column.dtype }}</small></th><th v-for="column in rowLabelColumns" :key="'label-' + column.id" class="custom-label-column"><span><Tags :size="11" /> {{ column.name }}</span><small>自定义标签 · {{ column.type === 'single' ? '单选' : column.type === 'multi' ? '多选' : '文本' }}</small></th><th>样本操作</th></tr></thead><tbody>
          <tr v-for="row in rows" :key="rowIdFor(row) || indexFor(row)"><td class="row-index"><button :aria-label="`查看第 ${rowNumber(row)} 条详情`" @click="openRow(row)"><span>{{ rowNumber(row) }}</span><ExternalLink :size="13"/></button></td><td v-for="column in columns" :key="column.name"><button v-if="linked(row[column.name])" class="file-link" @click="emit('open', String(row[column.name]))"><FileText :size="13" />{{ row[column.name] }}</button><details v-else-if="row[column.name] !== null && typeof row[column.name] === 'object'" class="cell-json"><summary>{{ Array.isArray(row[column.name]) ? '数组' : 'JSON 对象' }} · 展开</summary><pre>{{ pretty(row[column.name]) }}</pre></details><button v-else-if="String(row[column.name] ?? '').length > 160" class="long-cell" @click="openRow(row)">{{ String(row[column.name]).slice(0, 125) }}<span>… 查看全文</span></button><span v-else class="cell-value" :class="{ 'cell-null': row[column.name] === null }" :title="pretty(row[column.name])">{{ pretty(row[column.name]) }}</span></td><td v-for="column in rowLabelColumns" :key="'label-' + column.id" class="custom-label-column"><span v-if="Array.isArray(labelValue(row,column))" class="cell-labels"><i v-for="value in labelValue(row,column)" :key="String(value)">{{ value }}</i></span><span v-else-if="labelValue(row,column)" class="cell-labels"><i>{{ labelValue(row,column) }}</i></span><span v-else class="unset-label">未设置</span></td><td><button class="row-action" @click="openRow(row)">详情 / 标签</button></td></tr>
          <tr v-if="!rows.length"><td :colspan="columns.length + (rowLabelColumns.length || 0) + 2" class="empty">当前页没有匹配的行</td></tr>
        </tbody></table></div>
        <div class="table-pagination"><span class="muted">{{search?'本页匹配 '+rows.length+' 条 · ':''}}{{ preview.totalRows?.toLocaleString() }} 行 · 第 {{ page }} / {{ pageCount }} 页</span><div><span class="page-size">每页 {{preview.pageSize??pageSize}} 行</span><button class="btn btn-ghost" :disabled="page <= 1||loading" @click="changePage(page - 1)"><ArrowLeft :size="15" />上一页</button><button class="btn btn-ghost" :disabled="page >= pageCount||loading" @click="changePage(page + 1)">下一页<ArrowRight :size="15" /></button></div></div>
      </template>
      <div v-else-if="preview.kind === 'text'" class="code-preview"><div v-for="(line,index) in lines" :key="index"><span>{{ index + 1 }}</span><code>{{ line || ' ' }}</code></div></div>
      <div v-else-if="preview.kind === 'image'" class="image-preview"><img :src="rawUrl" :alt="path" /></div>
      <PdfPreview v-else-if="preview.kind === 'pdf'" :url="rawUrl" />
      <div v-else-if="preview.kind === 'audio'" class="media-preview"><audio :src="rawUrl" controls preload="metadata">当前浏览器不支持音频播放。</audio><p>{{ path }}</p></div>
      <div v-else-if="preview.kind === 'video'" class="media-preview"><video :src="rawUrl" controls preload="metadata">当前浏览器不支持视频播放。</video><p>{{ path }}</p></div>
      <ArchivePreview v-else-if="/\.zip$/i.test(path)" :base="base" :branch="viewCommit||branch" :path="path" :compact="compact"/>
      <div v-else class="empty"><Layers3 :size="32" /><h3>此文件可通过原文件查看</h3><p>{{ preview.mime }} · {{ preview.size.toLocaleString() }} bytes</p><a class="btn" :href="rawUrl" target="_blank" rel="noreferrer"><Download :size="15" />打开文件</a></div>
      <p v-if="preview.truncated" class="notice">预览内容已截断，可打开原文件查看完整内容。</p>
    </template>
    <div v-if="selectedRow" class="record-backdrop" @click.self="closeRow"><section class="record-dialog" role="dialog" aria-modal="true" aria-labelledby="record-title" @keydown.esc="closeRow"><header><div><h3 id="record-title">样本 {{ selectedRow.ordinal }}</h3><code>{{ viewCommit.slice(0, 12) }} · {{ path }}</code></div><button class="icon-button" aria-label="关闭样本详情" @click="closeRow"><X :size="19" /></button></header><p class="record-note">原始样本文本与嵌套 JSON 仅供阅读，内容不会作为指令执行。</p><div class="record-body"><dl><template v-for="(value,key) in selectedRow.record" :key="key"><dt>{{ key }}</dt><dd><details v-if="value !== null && typeof value === 'object'"><summary>展开 JSON</summary><pre>{{ pretty(value) }}</pre></details><pre v-else>{{ pretty(value) }}</pre></dd></template></dl><section v-if="!compact" class="record-labels"><LabelManager v-if="selectedRow.rowId" ref="rowLabelEditor" :base="base" :branch="branch" scope="row" :path="path" :row-id="selectedRow.rowId" :commit-id="viewCommit" @changed="labelsChanged" @loaded="labels = $event" @refresh="refresh" /><p v-else class="notice">没有稳定行标识，暂不能为此行赋值。</p><RouterLink :to="annotationLink(selectedRow.record)" class="btn btn-ghost"><Tags :size="14" />在标注工作台中打开</RouterLink></section></div><footer class="record-pagination"><span>{{selectedRow.ordinal.toLocaleString()}} / {{preview?.totalRows?.toLocaleString()||'—'}} 条记录</span><div><button class="btn" :disabled="selectedRow.ordinal<=1||loading" @click="moveRow(-1)"><ArrowLeft :size="14"/>上一条</button><button class="btn" :disabled="selectedRow.ordinal>=(preview?.totalRows??0)||loading" @click="moveRow(1)">下一条<ArrowRight :size="14"/></button></div></footer></section></div>
  </section>
</template>

<style scoped>
.file-preview{min-width:0;background:var(--surface);color:var(--text)}.preview-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:64px;padding:13px 18px;border-bottom:1px solid var(--line)}.resource-title,.resource-actions{display:flex;align-items:center;gap:9px;min-width:0}.resource-title>svg{color:var(--muted)}.resource-title strong{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.resource-title .badge{font-size:10px}.resource-size{font-size:11px;color:var(--muted);white-space:nowrap}.resource-actions{gap:4px;flex-shrink:0}.resource-actions .btn{padding:7px 9px;min-height:32px;font-size:12px}.preview-version{font:11px Consolas,monospace;color:var(--muted);padding:4px 7px;border:1px solid var(--line);border-radius:4px;white-space:nowrap;background:var(--surface-raised)}.file-label-manager{padding:22px;border-bottom:1px solid var(--line);background:var(--surface-raised)}.scope-badges{display:flex;gap:7px;flex-wrap:wrap;padding:11px 18px;background:var(--surface-raised);border-bottom:1px solid var(--line)}.scope-badges>span{display:inline-flex;align-items:center;gap:7px;font-size:12px;padding:4px 8px;background:color-mix(in srgb,var(--primary) 10%,var(--surface));border:1px solid color-mix(in srgb,var(--primary) 30%,var(--line));border-radius:4px;color:var(--text)}.scope-badges small{font-size:10px;color:var(--muted)}.scope-badges strong{font-weight:550}.dataset-query-bar{display:flex;align-items:center;gap:12px;margin:18px 18px 0;padding:6px 6px 6px 14px;border:1px solid var(--line);border-radius:7px;background:var(--bg);color:var(--muted)}.dataset-query-bar:focus-within{border-color:var(--primary);box-shadow:0 0 0 3px color-mix(in srgb,var(--primary) 13%,transparent)}.dataset-query-bar input{min-width:0;width:100%;flex:1;border:0;outline:0;background:transparent;color:var(--text);font-size:13px;line-height:1.5;padding:8px 0}.dataset-query-bar input::placeholder{color:var(--muted)}.dataset-query-bar .btn{font-size:12px;min-height:34px;background:var(--surface-raised)}.table-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px}.table-metadata{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted)}.table-metadata>strong{font-size:13px;color:var(--text);font-weight:600}.table-metadata strong>span{font-weight:400;color:var(--muted)}.table-tool-actions{display:flex;align-items:center;gap:9px}.table-tool-actions .search-field{width:190px;height:32px}.table-tool-actions .search-field input{font-size:12px}.table-tool-actions>.btn{font-size:12px;min-height:32px;padding:6px 9px}.table-label-error{font-size:12px;padding:10px 18px;color:var(--warning,#d5b56a)}.table-scroll{overflow:auto;max-height:64vh;border-top:1px solid var(--line);overscroll-behavior:contain}.preview-table{border-collapse:separate;border-spacing:0;table-layout:auto;width:max-content;min-width:100%;font-size:13px}.preview-table th{position:sticky;top:0;z-index:3;text-align:left;min-width:140px;max-width:380px;padding:12px 14px;background:var(--surface-raised);border-right:1px solid var(--line);border-bottom:1px solid var(--line);font-size:12px;color:var(--text);font-weight:550;white-space:nowrap}.preview-table th small{display:block;font:10px Consolas,monospace;color:var(--muted);margin-top:5px}.preview-table td{vertical-align:top;padding:12px 14px;min-width:140px;max-width:380px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);font-size:13px;color:var(--text);line-height:1.55}.preview-table tr:hover>td{background:var(--surface-raised)}.preview-table .row-index{position:sticky;left:0;width:74px;min-width:74px;padding:0;background:var(--surface-raised);text-align:center;z-index:2;color:var(--muted);font-size:11px}.preview-table th.row-index{z-index:5;padding:12px}.row-index button{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;height:100%;min-height:43px;paddin